const path=location.pathname.split('/').filter(Boolean);const lang=path[0]==='es'?'es':'en';const es=lang==='es';const page=path.slice(1).join('/')||'home';
const anatomyPage=page==='how-websites-connect'?(await import('/anatomy-page.js')).anatomyPage:null;
const aiAgentsPage=page==='how-ai-agents-work'?(await import('/ai-agents-page.js')).aiAgentsPage:null;
const chapterStyles=page==='how-websites-connect'?['/vendor/anatomy/iso.css','/anatomy-page.css']:page==='how-ai-agents-work'?['/vendor/anatomy/iso.css','/ai-operations.css']:[];await Promise.all(chapterStyles.map(href=>new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href=href;css.onload=resolve;css.onerror=()=>reject(new Error('Stylesheet unavailable: '+href));document.head.append(css);})));
const t=(en,sp)=>es?sp:en;const home=`/${lang}`;const lp=slug=>`/${lang}/services/${slug}`;
const arrow='<span aria-hidden="true">↗</span>';const btn=(label,attrs='',outline=false)=>`<button class="button ${typeof outline==='string'?outline:outline?'outline':''}" ${attrs}>${label}${arrow}</button>`;const link=(label,href,cls='text-link')=>`<a class="${cls}" href="${href}">${label}${arrow}</a>`;
const sectionHead=(n,label,right='')=>`<div class="section-line"><span>${n} / ${label}</span><span>${right}</span></div>`;
const priority=[
 ['one-page-websites','One-page websites','Sitios de una página'],['business-websites','Business websites','Sitios empresariales'],['e-commerce','E-commerce development','Desarrollo e-commerce']
];
const taxonomy=[
 [t('Digital experiences','Experiencias digitales'),[t('Website Development','Desarrollo web'),t('E-commerce Development','Desarrollo e-commerce'),t('Custom Software Development','Desarrollo de software a medida')]],
 [t('Intelligence & operations','Inteligencia y operaciones'),[t('AI Solutions','Soluciones de IA'),t('AI Agents','Agentes de IA'),t('AI Marketing Automation','Automatización de marketing con IA'),t('CRM Implementation','Implementación de CRM')]],
 [t('Brand & creative','Marca y creatividad'),[t('Branding & Visual Identity','Branding e identidad visual'),t('Graphic Design','Diseño gráfico'),t('Video Production & Editing','Producción y edición de video')]],
 [t('Demand & acquisition','Demanda y captación'),['Meta Ads','Google Ads','TikTok Ads',t('Lead Generation','Generación de oportunidades'),t('Marketing & Growth Consulting','Consultoría de marketing y crecimiento')]],
 [t('Content & relationships','Contenido y relaciones'),[t('Social Media Management','Gestión de redes sociales'),'SEO',t('Content Marketing','Marketing de contenidos'),t('Email Marketing','Email marketing')]]
];
const faq=[
 [t('How do we get started?','¿Cómo comenzamos?'),t('Tell us about your business, your audience and the problem you want to solve. We’ll recommend a direction and prepare a proposal around your goals.','Cuéntanos sobre tu negocio, tus clientes y lo que quieres resolver. Definiremos una dirección y prepararemos una propuesta según tus objetivos.')],
 [t('Can you improve our existing website?','¿Pueden mejorar un sitio existente?'),t('Yes. We first review your content, structure and customer journey, then recommend focused improvements or a redesign based on what the business needs.','Sí. Primero revisamos el contenido, la estructura y el recorrido de tus clientes. Después recomendamos mejoras concretas o un rediseño según lo que necesite el negocio.')],
 [t('What can an AI agent do for our business?','¿Qué puede hacer un agente de IA por mi negocio?'),t('An agent can answer approved questions, collect inquiry details, qualify leads and hand off to your team. Channels, permissions and escalation rules are defined for each project.','Puede responder preguntas con información aprobada, recoger datos de consultas, clasificar oportunidades y derivarlas a tu equipo. Los canales, permisos y reglas de derivación se definen para cada proyecto.')],
 [t('Can AI connect with our CRM?','¿La IA puede conectarse con nuestro CRM?'),t('We assess the systems you use, their available integrations and the workflow you need. The proposed connections and human review steps are agreed before development.','Evaluamos los sistemas que utilizas, sus integraciones disponibles y el flujo que necesitas. Las conexiones propuestas y los pasos de revisión humana se acuerdan antes del desarrollo.')],
 [t('Can we combine web, branding and marketing?','¿Podemos combinar web, branding y marketing?'),t('Yes. We can define a connected scope across identity, website, content and acquisition so every part of the experience follows the same strategy.','Sí. Podemos definir un alcance que conecte identidad, sitio web, contenido y captación para que toda la experiencia siga una misma estrategia.')],
 [t('How long does a project take?','¿Cuánto tarda un proyecto?'),t('Timing depends on scope, content, integrations and review cycles. Your proposal sets out the stages, responsibilities and milestones before we begin.','Depende del alcance, el contenido, las integraciones y las revisiones. La propuesta define etapas, responsabilidades e hitos antes de comenzar.')],
 [t('How do custom proposals work?','¿Cómo funcionan las propuestas a medida?'),t('Every project is scoped individually. We discuss your goals, priorities and requirements, then prepare a clear proposal. We do not use public price lists or automated estimates.','Cada proyecto se define de forma individual. Conversamos sobre objetivos, prioridades y requisitos para preparar una propuesta clara. No usamos tarifas públicas ni estimaciones automáticas.')],
 [t('Is ongoing support available?','¿Ofrecen acompañamiento después del lanzamiento?'),t('Support, maintenance and continued improvement can be included in the agreed scope. We define what is covered and how we will work together after launch.','El soporte, mantenimiento y las mejoras pueden incluirse en el alcance acordado. Definimos qué cubre el acompañamiento y cómo trabajaremos después del lanzamiento.')]
];
function header(){return `<div class="review-bar"><span>CONNEXION / ${t('DESIGN REVIEW · PHASE 01','REVISIÓN DE DISEÑO · FASE 01')}</span><a href="/${lang}/review">${t('Review all designs','Ver todos los diseños')} ↗</a></div><header class="header"><a href="${home}" class="brand"><img src="/assets/logo-${page.startsWith('services/')?'light':'dark'}.webp" alt="Connexion" width="645" height="95"></a><nav aria-label="${t('Main navigation','Navegación principal')}"><a href="${home}#solutions">${t('Solutions','Soluciones')}</a><a href="${home}#intelligence">${t('Intelligence','Inteligencia')}</a><a href="${home}#work">${t('Our work','Proyectos')}</a><a href="${home}#about">${t('The agency','La agencia')}</a></nav><div class="header-actions"><div class="languages"><a href="/en${page==='home'?'':'/'+page}" aria-current="${!es?'page':'false'}">EN</a><a href="/es${page==='home'?'':'/'+page}" aria-current="${es?'page':'false'}">ES</a></div>${btn(t('Let’s connect','Conectemos'),'data-proposal','header-cta')}<button class="menu-toggle" aria-label="${t('Open menu','Abrir menú')}" aria-expanded="false" aria-controls="mobile-menu"><i></i><i></i></button></div></header><nav id="mobile-menu" class="mobile-menu" hidden>${link(t('Solutions','Soluciones'),`${home}#solutions`)}${link(t('Intelligence','Inteligencia'),`${home}#intelligence`)}${link(t('Our work','Proyectos'),`${home}#work`)}${link(t('The agency','La agencia'),`${home}#about`)}${link(t('How AI agents work','Cómo funciona un agente de IA'),`/${lang}/how-ai-agents-work`)}${link(t('All design proposals','Todas las propuestas'),`/${lang}/review`)}</nav>`;}
function footer(){return `<footer class="footer"><div class="wrap footer-top"><div><img src="/assets/logo-dark.webp" alt="Connexion" width="1800" height="330"><p>${t('Technology creates possibilities.<br>Human connection creates value.','La tecnología crea posibilidades.<br>La conexión humana crea valor.')}</p><span class="micro">UNITED STATES ↔ COLOMBIA / EN · ES</span></div><div><span class="micro">${t('EXPLORE','EXPLORA')}</span><a href="${home}#solutions">${t('Solutions','Soluciones')}</a><a href="${home}#work">${t('Selected work','Proyectos')}</a><a href="${home}#process">${t('Our process','Proceso')}</a><a href="/${lang}/how-ai-agents-work">${t('How AI agents work','Cómo funciona un agente de IA')}</a><a href="${home}#faq">FAQ</a></div><div><span class="micro">${t('WEBSITE SOLUTIONS','SOLUCIONES WEB')}</span>${priority.map(([s,en,sp])=>`<a href="${lp(s)}">${t(en,sp)}</a>`).join('')}<a href="/${lang}/how-websites-connect">${t('How your website works','Cómo trabaja tu web')}</a></div><div><span class="micro">${t('START A CONVERSATION','CONVERSEMOS')}</span><a href="mailto:info@connexion.co">info@connexion.co ↗</a><a href="https://wa.me/13214513964" target="_blank" rel="noopener">WhatsApp ↗</a><button data-meeting>${t('Request a meeting','Solicitar reunión')} ↗</button></div></div><div class="wrap footer-bottom"><span>© 2026 CONNEXION</span><span>${t('WE CONNECT BRANDS WITH PEOPLE.','CONECTAMOS MARCAS CON PERSONAS.')}</span><span>${t('United States ↔ Colombia','Estados Unidos ↔ Colombia')}</span></div></footer><a class="whatsapp" href="https://wa.me/13214513964" target="_blank" rel="noopener" aria-label="WhatsApp Connexion"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M20 11.5a8 8 0 0 1-12 7L3 20l1.5-5A8 8 0 1 1 20 11.5Z"/><path d="M8 7c0 5 4 8 8 8l1-2-3-1-1 1-3-3 1-1-1-2Z"/></svg></a>`;}
function hero(){return `<section class="hero-scroll" id="hero"><div class="hero-pin"><div class="corporate-photo" aria-hidden="true"></div><div class="hero-atmosphere" aria-hidden="true"><svg viewBox="0 0 1440 900" preserveAspectRatio="none"><defs><filter id="connection-glow" x="-60%" y="-100%" width="220%" height="300%"><feGaussianBlur stdDeviation="15"/></filter></defs><path class="ribbon-glow" d="M-100 760C260 530 410 960 800 450S1110 170 1510 -70"/><path class="ribbon-edge" d="M-100 760C260 530 410 960 800 450S1110 170 1510 -70"/><path class="ribbon-secondary" d="M-100 820C370 540 670 980 1120 590S1390 460 1510 300"/></svg></div><div class="wrap hero-topline"><span><i class="status-dot"></i> ${t('AI SOLUTIONS & DIGITAL GROWTH','SOLUCIONES DE IA Y CRECIMIENTO DIGITAL')}</span><span>HUMAN IDEAS. INTELLIGENT CONNECTIONS.</span></div><div class="hero-engine"><img class="engine-poster" src="/assets/symbol-poster.webp" alt=""/><canvas id="engine" aria-hidden="true"></canvas><div class="engine-tags" aria-hidden="true"><span>${t('BRANDS','MARCAS')}</span><span>AI</span><span>${t('PEOPLE','PERSONAS')}</span><span>${t('OPPORTUNITIES','OPORTUNIDADES')}</span></div></div><div class="wrap hero-copy"><h1>${t('We connect<br>brands with<br><span>people.</span>','Conectamos<br>marcas con<br><span>personas.</span>')}</h1><p>${t('AI-powered solutions, digital experiences, and marketing strategies built to grow your business.','Soluciones de IA, experiencias digitales y estrategias de marketing para impulsar tu negocio.')}</p><div class="actions">${btn(`<span class="cta-full">${t('GET A CUSTOM PROPOSAL','SOLICITA UNA PROPUESTA')}</span><span class="cta-short">${t('Get a proposal','Tu propuesta')}</span>`,'data-proposal')}${link(`<span class="cta-full">${t('Explore our solutions','Explora nuestras soluciones')}</span><span class="cta-short">${t('Solutions','Soluciones')}</span>`,'#solutions')}</div><div class="hero-markets"><span>${t('Built around your business.','Pensado para tu negocio.')}</span><span>ENGLISH / ESPAÑOL</span></div></div><div class="wrap hero-rail"><div class="hero-scroll-cue">↓ <span>${t('SCROLL TO CONNECT','DESLIZA PARA CONECTAR')}</span></div><div class="hero-caption" id="hero-caption">${t('Great ideas begin with a connection.','Las grandes ideas comienzan con una conexión.')}</div><div class="hero-stages" role="group" aria-label="${t('Hero scenes','Escenas del hero')}">${[t('Symbol','Símbolo'),t('Activation','Activación'),t('Connections','Conexiones'),t('Reveal','Revelación')].map((s,i)=>`<button data-stage="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${s}</button>`).join('')}</div></div><div class="hero-line"></div></div></section><div class="hero-mobile-summary wrap"><p>${t('AI-powered solutions, digital experiences, and marketing strategies built to grow your business.','Soluciones de IA, experiencias digitales y estrategias de marketing para impulsar tu negocio.')}</p></div>`;}
function miniBrowser(kind='business'){return `<div class="browser-concept ${kind}"><div class="browser-top"><i></i><i></i><i></i><span>${t('Website concept','Concepto web')}</span></div><div class="concept-nav"><b>${t('YOUR BRAND','TU MARCA')}</b><span>${t('Discover / About / Contact','Explora / Nosotros / Contacto')}</span></div><div class="concept-body"><span class="micro">${t('A NEW PERSPECTIVE','UNA NUEVA PERSPECTIVA')}</span><strong>${t('Your next chapter.<br>Built around you.','Tu próxima etapa.<br>Pensada para ti.')}</strong><div class="concept-object"><i></i><i></i><i></i></div><span class="concept-cta">${t('Let’s begin','Comencemos')} ↗</span></div><div class="concept-bottom"><span>${t('Considered design. Clear purpose.','Diseño con criterio. Propósito claro.')}</span><span>01 / 03</span></div></div>`;}
function visualIcon(kind){const paths={web:'<rect x="4" y="5" width="24" height="21" rx="3"/><path d="M4 11h24M9 8h1m3 0h1M11 16l-3 3 3 3m10-6 3 3-3 3m-6 1 2-8"/>',ai:'<path d="M16 3l4 7 8 2-5 7 1 9-8-3-8 3 1-9-5-7 8-2Z"/><circle cx="16" cy="16" r="4"/>',people:'<circle cx="11" cy="9" r="4"/><circle cx="23" cy="11" r="3"/><path d="M3 27v-4a8 8 0 0 1 16 0v4m2-10a6 6 0 0 1 8 6v4"/>',health:'<path d="M12 4h8v8h8v8h-8v8h-8v-8H4v-8h8Z"/>',dental:'<path d="M16 7C5-1 2 10 7 18c3 5 1 11 5 10 3-1 1-8 4-8s1 7 4 8c4 1 2-5 5-10C30 10 27-1 16 7Z"/>',cleaning:'<path d="M16 3l4 9 9 4-9 4-4 9-4-9-9-4 9-4ZM26 3v6m-3-3h6"/>',car:'<path d="M4 24V14l4-7h16l4 7v10M4 14h24M4 23h24M7 24v4m18-4v4M8 18h4m8 0h4"/>',home:'<path d="M3 15 16 4l13 11M7 13v15h18V13m-13 15V18h8v10"/>'};return `<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.web}</svg>`;}
function systemsArt(){const nodes=[['web',t('WEBSITES','SITIOS WEB')],['ai',t('INTELLIGENCE','INTELIGENCIA')],['people',t('PEOPLE','PERSONAS')]];return `<figure class="section-art systems-art visual-reveal" aria-label="${t('Websites, intelligence and people connected in one system','Sitios web, inteligencia y personas conectados en un sistema')}"><svg class="system-wires" viewBox="0 0 600 210" aria-hidden="true"><path class="art-route signal-path" d="M90 140C170 140 210 70 300 70S430 140 510 140"/><circle class="art-signal" r="5"/></svg><div class="systems-nodes">${nodes.map(([icon,title],i)=>`<div class="system-node ${i===1?'system-feature':''}">${visualIcon(icon)}<strong>${title}</strong></div>`).join('')}</div><figcaption>${t('Your presence. Your operations. Your relationships. Connected.','Tu presencia. Tu operación. Tus relaciones. Conectadas.')}</figcaption></figure>`;}
function orbitArt(purpose=false){const labels=purpose?[t('STRATEGY','ESTRATEGIA'),t('CREATIVITY','CREATIVIDAD'),t('PEOPLE','PERSONAS'),t('TECHNOLOGY','TECNOLOGÍA')]:['WEB',t('AI','IA'),t('BRAND','MARCA'),t('CONTENT','CONTENIDO'),t('GROWTH','CRECIMIENTO')];const nodes=purpose?[[110,65],[490,65],[490,235],[110,235]]:[[300,35],[500,105],[430,260],[170,260],[100,105]];return `<figure class="section-art orbit-art visual-reveal" aria-label="${t('A connected ecosystem around the Connexion symbol','Un ecosistema conectado alrededor del símbolo Connexion')}"><svg viewBox="0 0 600 320" role="img"><ellipse class="art-orbit" cx="300" cy="155" rx="206" ry="112"/>${nodes.map(([x,y],i)=>`<path class="art-route ${i===0?'signal-path':''}" d="M300 155 Q${x} 155 ${x} ${y}"/><g class="art-node"><circle class="art-orbit-node" cx="${x}" cy="${y}" r="22"/><circle class="art-orbit-dot" cx="${x}" cy="${y}" r="5"/></g>`).join('')}<circle class="art-center" cx="300" cy="155" r="59"/><image href="/assets/symbol-art.webp" x="258" y="125" width="84" height="60"/><circle class="art-signal" r="5"/></svg><figcaption class="orbit-legend">${labels.map(label=>`<span>${label}</span>`).join('')}</figcaption></figure>`;}
function conversationArt(){return `<figure class="section-art conversation-art visual-reveal" aria-hidden="true"><svg viewBox="0 0 450 210"><path class="art-route signal-path" d="M65 85C140 85 120 160 220 130S300 55 385 90"/><rect class="art-bubble" x="20" y="42" width="125" height="73" rx="15"/><path class="art-route" d="m45 115-8 18 28-18"/><rect class="art-bubble" x="300" y="50" width="125" height="73" rx="15"/><path class="art-route" d="m370 123 24 16-5-16"/><path class="art-rule" d="M46 66h65M46 83h44M326 74h65M326 91h44"/><circle class="art-center" cx="225" cy="130" r="48"/><image href="/assets/symbol-art.webp" x="190" y="104" width="70" height="51"/><circle class="art-signal" r="5"/></svg></figure>`;}
function coreServices(){return `<section class="section core" id="solutions"><div class="wrap">${sectionHead('03',t('OUR CORE CAPABILITIES','NUESTRAS CAPACIDADES CLAVE'),t('THREE WAYS TO MOVE FORWARD','TRES FORMAS DE AVANZAR'))}<div class="section-heading"><h2>${t('The right tools.<br><span>A human purpose.</span>','Las herramientas correctas.<br><span>Un propósito humano.</span>')}</h2><p>${t('Build your presence. Connect your operations. Give your team intelligent support.','Construye tu presencia. Conecta tus operaciones. Dale apoyo inteligente a tu equipo.')}</p></div><div class="core-showcase"><article class="core-web"><div class="core-text"><span class="micro">01 / DIGITAL EXPERIENCES</span><h3>${t('Websites that open<br>new doors.','Sitios web que abren<br>nuevas puertas.')}</h3><p>${t('From a focused landing page to a custom digital platform, we build around how your customers discover, understand and choose your business.','Desde una landing enfocada hasta una plataforma a medida, diseñamos para que tus clientes descubran, entiendan y elijan tu negocio.')}</p><div class="service-pills"><span>${t('One-page websites','Sitios de una página')}</span><span>${t('Business websites','Sitios empresariales')}</span><span>E-commerce</span></div>${link(t('Explore website solutions','Explora las soluciones web'),lp('business-websites'))}</div><figure class="web-visual">${miniBrowser()}<figcaption>${t('Illustrative design concept — not a client project.','Concepto visual ilustrativo; no es un proyecto de cliente.')}</figcaption></figure></article><div class="core-pair"><article class="core-ai"><span class="micro">02 / INTELLIGENT OPERATIONS</span><div class="connection-diagram" aria-hidden="true"><svg viewBox="0 0 480 230"><path d="M65 150C160 150 110 50 240 60S330 175 415 150"/><path d="M65 150C160 230 320 230 415 150"/><circle cx="65" cy="150" r="28"/><circle cx="240" cy="60" r="45"/><circle cx="415" cy="150" r="28"/></svg><span>INPUT</span><span>INTELLIGENCE</span><span>ACTION</span></div><h3>${t('Less friction.<br>More possibility.','Menos fricción.<br>Más posibilidades.')}</h3><p>${t('Connect your workflows, CRM and business processes with AI solutions designed around the way your team works.','Conecta flujos, CRM y procesos con soluciones de IA pensadas para la forma de trabajar de tu equipo.')}</p>${btn(t('Explore AI solutions','Explora soluciones de IA'),'data-proposal data-interest="AI Solutions"',true)}</article><article class="core-agents"><span class="micro">03 / AI AGENTS</span><div class="agent-visual" aria-hidden="true"><div class="agent-core"><i></i><i></i><i></i></div><span class="agent-note note-a">${t('INQUIRY RECEIVED','CONSULTA RECIBIDA')}</span><span class="agent-note note-b">${t('CONTEXT UNDERSTOOD','CONTEXTO IDENTIFICADO')}</span><span class="agent-note note-c">${t('HUMAN HANDOFF','DERIVACIÓN AL EQUIPO')}</span></div><h3>${t('An intelligent first response.<br>A human next step.','Una primera respuesta inteligente.<br>Un siguiente paso humano.')}</h3><p>${t('Customer service agents, sales assistants and lead management that help people reach the right answer — and the right person.','Agentes de atención, asistentes de ventas y gestión de oportunidades que ayudan a encontrar la respuesta y la persona adecuadas.')}</p>${link(t('See an agent in action','Mira un agente en acción'),`/${lang}/how-ai-agents-work`,'text-link agent-page-link')}${btn(t('Explore AI agents','Explora agentes de IA'),'data-proposal data-interest="AI Agents"',true)}</article></div></div></div></section>`;}
function ecosystem(){return `<section class="section ecosystem"><div class="wrap ecosystem-grid"><div>${sectionHead('04',t('ONE CONNECTED ECOSYSTEM','UN ECOSISTEMA CONECTADO'))}<h2>${t('Every part.<br>The same direction.','Cada parte.<br>Una misma dirección.')}</h2><p>${t('Bring your brand, content, campaigns and systems together. We define the mix around your goals, not a fixed package.','Conecta marca, contenido, campañas y sistemas. Definimos la combinación según tus objetivos, no con un paquete fijo.')}</p>${orbitArt()}</div><div class="service-ecosystem">${taxonomy.map(([title,items],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${title}<b>+</b></summary><div>${items.map(item=>`<button data-proposal data-interest="${item}">${item}<span>↗</span></button>`).join('')}</div></details>`).join('')}</div></div></section>`;}
function workflow(){const steps=[t('New lead','Nueva oportunidad'),t('AI agent','Agente de IA'),'CRM',t('Follow-up','Seguimiento'),t('Your team','Tu equipo')];return `<section class="section intelligence" id="intelligence"><div class="wrap">${sectionHead('05',t('AI WITH A PRACTICAL PURPOSE','IA CON UN PROPÓSITO PRÁCTICO'),t('CONNECTION ENGINE / WORKFLOW STUDY','CONNECTION ENGINE / ESTUDIO DE FLUJO'))}<div class="section-heading"><h2>${t('Intelligence that works<br><span>for your business.</span>','Inteligencia que trabaja<br><span>para tu negocio.</span>')}</h2><p>${t('Turn a first inquiry into a clear next step. With the right information, connected systems and people in control.','Convierte una primera consulta en un siguiente paso claro. Con información adecuada, sistemas conectados y personas al mando.')}</p></div><div class="workflow" role="group" aria-label="${t('Illustrative business workflow','Flujo de negocio ilustrativo')}">${steps.map((s,i)=>`<button data-workflow="${i}" aria-pressed="${i===1}"><span class="flow-node">${['↗','✳','▤','↗','↗'][i]}</span><small>0${i+1}</small><strong>${s}</strong>${i<4?'<i aria-hidden="true">→</i>':''}</button>`).join('')}</div><div class="workflow-explanation"><div><span class="micro">${t('SELECT A STEP TO EXPLORE','ELIGE UN PASO PARA EXPLORAR')}</span><h3 id="workflow-title">${t('Useful context, before the handoff.','Contexto útil antes de la derivación.')}</h3><p id="workflow-copy">${t('An agent can collect the right details, answer approved questions and identify when your team should take over.','Un agente puede reunir los datos necesarios, responder con información aprobada e identificar cuándo debe intervenir tu equipo.')}</p></div><p class="workflow-disclaimer">${t('Illustrative workflow. Systems, integrations, permissions and human review are scoped for each project. This is not a live Connexion product.','Flujo ilustrativo. Sistemas, integraciones, permisos y revisión humana se definen para cada proyecto. No es un producto activo de Connexion.')}</p></div></div></section>`;}
function processSection(){return `<section class="section process" id="process"><div class="wrap">${sectionHead('06',t('HOW WE THINK. HOW WE BUILD.','CÓMO PENSAMOS. CÓMO CONSTRUIMOS.'))}<div class="section-heading"><h2>${t('A clear direction.<br>A connected process.','Una dirección clara.<br>Un proceso conectado.')}</h2><p>${t('Strategy makes it relevant. Creativity makes it distinctive. Connection makes it useful.','La estrategia le da relevancia. La creatividad lo hace propio. La conexión lo vuelve útil.')}</p></div><div class="process-route" aria-hidden="true"><svg viewBox="0 0 1100 170"><path d="M50 100C250 100 230 20 480 55S800 170 1050 45"/><circle cx="50" cy="100" r="8"/><circle cx="520" cy="65" r="8"/><circle cx="1050" cy="45" r="8"/></svg></div><div class="process-tabs" role="tablist" aria-label="${t('Our process','Nuestro proceso')}">${[t('Strategy','Estrategia'),t('Creativity','Creatividad'),t('Connection','Conexión')].map((s,i)=>`<button role="tab" id="process-${i}" aria-controls="process-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-process="${i}"><span>0${i+1}</span>${s}${arrow}</button>`).join('')}</div><div class="process-panel" id="process-panel" role="tabpanel" aria-labelledby="process-0"><h3>${t('Understand what matters.','Entender lo que importa.')}</h3><p>${t('We listen to your team, understand your customers and define the problem worth solving. Scope and priorities come before execution.','Escuchamos a tu equipo, entendemos a tus clientes y definimos el problema que vale la pena resolver. Primero el alcance y las prioridades; después la ejecución.')}</p><span>${t('DISCOVERY → DIRECTION → SHARED SCOPE','DESCUBRIMIENTO → DIRECCIÓN → ALCANCE COMPARTIDO')}</span></div></div></section>`;}
