function portfolio(){return `<section class="section work" id="work"><div class="wrap">${sectionHead('07',t('SELECTED WORK','PROYECTOS SELECCIONADOS'),t('DIFFERENT INDUSTRIES. ONE CONNECTED APPROACH.','DISTINTOS SECTORES. UNA VISIÓN CONECTADA.'))}<div class="section-heading"><h2>${t('Connections you<br>can see.','Conexiones que<br>puedes ver.')}</h2><p>${t('Explore a selection of websites we have created for businesses and organizations across different industries.','Explora una selección de sitios que hemos creado para empresas y organizaciones de distintos sectores.')}</p></div><div class="portfolio-grid">${portfolioProjects.map(project=>`<article class="case-${project.id}" data-project="${project.id}"><a class="project-screen" href="${project.url}" target="_blank" rel="noopener"><div class="project-browser"><i></i><i></i><i></i><span>${new URL(project.url).hostname}</span>${arrow}</div><img src="/assets/work-${project.image}.webp" alt="${t('Website screenshot:','Captura del sitio:')} ${project.name}" width="1440" height="1000" loading="lazy"></a><div class="case-caption"><div><span class="micro">${project.category}</span><h3>${project.name}</h3></div><a class="project-visit" href="${project.url}" target="_blank" rel="noopener" aria-label="${t('Visit','Visitar')} ${project.name}">${arrow}</a></div></article>`).join('')}</div></div></section>`;}
function industries(){return `<section class="section industries"><div class="wrap industries-grid"><div>${sectionHead('08',t('YOUR INDUSTRY. YOUR CONTEXT.','TU SECTOR. TU CONTEXTO.'))}<h2>${t('Different worlds.<br><span>Human at the center.</span>','Distintos mundos.<br><span>Las personas, al centro.</span>')}</h2><p>${t('We shape the solution around your customers, operations and sector. We work across sectors, with special attention to these business contexts.','Adaptamos la solución a tus clientes, operaciones y sector. Trabajamos en distintos sectores, con especial atención a estos contextos de negocio.')}</p></div><div class="industry-list">${[[t('Healthcare','Salud'),t('Clear information. Easier inquiries.','Información clara. Consultas más sencillas.')],[t('Dental','Odontología'),t('From the first question to your team.','De la primera pregunta a tu equipo.')],[t('Cleaning services','Limpieza'),t('Make your standards visible.','Haz visibles tus estándares.')],[t('Automotive','Automotriz'),t('Connect inventory with opportunity.','Conecta inventario y oportunidades.')],[t('Real estate','Bienes raíces'),t('Help people find their next step.','Ayuda a encontrar el siguiente paso.')]].map(([s,d],i)=>`<button data-proposal data-interest="${s}"><span class="industry-symbol">${visualIcon(['health','dental','cleaning','car','home'][i])}</span><div><strong>${s}</strong><small>${d}</small></div><b>↗</b></button>`).join('')}<p>${t('A different industry? Let’s talk about your business.','¿Trabajas en otro sector? Conversemos sobre tu negocio.')}</p></div></div></section>`;}
function why(){return `<section class="section why"><div class="wrap">${sectionHead('09',t('WHY CONNEXION','POR QUÉ CONNEXION'))}<div class="why-grid"><div class="why-intro"><h2>${t('More connected.<br><span>More considered.</span>','Más conectado.<br><span>Mejor pensado.</span>')}</h2>${orbitArt(true)}</div><div class="why-principles">${[[t('People before platforms','Personas antes que plataformas'),t('We begin with the people who will use the experience.','Empezamos por quienes van a vivir la experiencia.')],[t('Intelligence with direction','Inteligencia con dirección'),t('AI serves a clear business goal, not the other way around.','La IA responde a un objetivo de negocio, no al revés.')],[t('One connected view','Una visión integrada'),t('Identity, experience, acquisition and operations work together.','Identidad, experiencia, captación y operaciones trabajan juntas.')],[t('Thoughtful execution','Ejecución con criterio'),t('Clear scope, creative craft and a shared path from idea to launch.','Alcance claro, cuidado creativo y un camino compartido de la idea al lanzamiento.')]].map(([h,p],i)=>`<article><span>0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div></div></div></section>`;}
function faqSection(items=faq){return `<section class="section faq-section" id="faq"><div class="wrap faq-grid"><div>${sectionHead('10',t('A FEW GOOD QUESTIONS','BUENAS PREGUNTAS'))}<h2>${t('Before the<br>first connection.','Antes de la<br>primera conexión.')}</h2><p>${t('Something else on your mind? We’re here to listen.','¿Tienes otra pregunta? Estamos para escucharte.')}</p>${btn(t('Let’s talk','Conversemos'),'data-proposal',true)}${conversationArt()}</div><div class="faq-list">${items.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}<b>+</b></summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function finalCTA(){return `<section class="section final-cta" id="proposal"><div class="wrap integral-contact-layout"><div class="integral-contact-copy"><div class="cta-line"><span class="status-dot"></span><span class="micro">${t('THE NEXT CONNECTION','LA PRÓXIMA CONEXIÓN')}</span></div><h2>${t('Your next great connection<br><span>starts here.</span>','Tu próxima gran conexión<br><span>comienza aquí.</span>')}</h2><img class="cta-symbol visual-reveal" src="/assets/symbol-poster.webp" alt="" width="725" height="520" loading="lazy"/><div class="cta-bottom"><p>${t('Tell us what you’re building.<br>We’ll help you find the right digital solution.','Cuéntanos lo que quieres construir.<br>Te ayudaremos a encontrar la solución digital adecuada.')}</p><div class="actions">${btn(t('REQUEST A PROPOSAL','SOLICITA UNA PROPUESTA'),'data-proposal')}${btn(t('CONTACT US','CONTÁCTANOS'),'data-meeting',true)}</div><div class="integral-contact-details"><a href="mailto:info@connexion.co">info@connexion.co ↗</a><a href="https://wa.me/13214513964" target="_blank" rel="noopener">WhatsApp ↗</a><span>UNITED STATES ↔ COLOMBIA</span></div></div></div><aside class="integral-contact-card"><h3>${t('Tell us about your project.','Cuéntanos sobre tu proyecto.')}</h3>${inlineContactForm()}</aside></div></section>`;}
function homepage(){return `${hero()}<section class="manifesto section" id="about"><div class="wrap">${sectionHead('01',t('THE WAY WE SEE IT','NUESTRA MIRADA'),t('HUMAN CREATIVITY × INTELLIGENT TECHNOLOGY','CREATIVIDAD HUMANA × TECNOLOGÍA INTELIGENTE'))}<h2>${t('Great brands don’t just<br>communicate.<br><span>They connect.</span>','Las grandes marcas no solo<br>comunican.<br><span>Conectan.</span>')}</h2><figure class="manifesto-visual visual-reveal"><img src="/assets/identity.webp" alt="${t('Connexion brand identity applied to business cards','Identidad de Connexion aplicada a tarjetas de presentación')}" width="800" height="500" loading="lazy"/><figcaption>${t('A DISTINCT IDENTITY. A SHARED PURPOSE.','UNA IDENTIDAD PROPIA. UN PROPÓSITO COMPARTIDO.')}</figcaption></figure><div class="manifesto-bottom"><span class="manifesto-arrow" aria-hidden="true">↗</span><p>${t('Technology creates possibilities.<br>Human connection creates value.','La tecnología crea posibilidades.<br>La conexión humana crea valor.')}</p><p>${t('We bring both together to help businesses build stronger experiences, work more intelligently and reach the people who matter.','Unimos ambas para crear mejores experiencias, trabajar de forma más inteligente y llegar a las personas que importan.')}</p></div></div></section><section class="section what"><div class="wrap what-grid">${sectionHead('02',t('WHAT WE DO','QUÉ HACEMOS'))}<h2>${t('Intelligent solutions.<br><span>Meaningful connections.</span>','Soluciones inteligentes.<br><span>Conexiones que importan.</span>')}</h2><div><p class="large-copy">${t('We build websites. Create brands. Connect business systems. And put AI to work where it can make a useful difference.','Creamos sitios web y marcas. Conectamos sistemas de negocio. Y aplicamos IA donde puede aportar una diferencia útil.')}</p><p>${t('Strategy, creativity and technology — shaped into a clear plan for your next stage of growth.','Estrategia, creatividad y tecnología convertidas en un plan claro para tu siguiente etapa de crecimiento.')}</p>${btn(t('Find your next step','Encuentra tu siguiente paso'),'data-proposal',true)}</div>${systemsArt()}</div></section>${coreServices()}${ecosystem()}${workflow()}${processSection()}${portfolio()}${industries()}${why()}${faqSection()}${finalCTA()}`;}
const landingData={
 'one-page-websites':{eyebrow:t('ONE-PAGE WEBSITES','SITIOS DE UNA PÁGINA'),title:t('One page.<br><span>A clear next step.</span>','Una página.<br><span>Un siguiente paso claro.</span>'),copy:t('A focused online presence that tells your story, explains your offer and makes it easy for the right people to get in touch.','Una presencia digital enfocada que cuenta tu historia, explica tu propuesta y facilita el contacto con las personas adecuadas.'),features:[t('One clear customer journey','Un recorrido claro para tus clientes'),t('Designed for every screen','Diseñado para cada pantalla'),t('Contact and lead capture','Contacto y captación de oportunidades')],benefit:t('Everything you need.<br>Nothing in the way.','Todo lo que necesitas.<br>Un camino sin obstáculos.'),explanation:t('A one-page website works best when your message is focused. We organize your story, services, proof and contact into one natural flow.','Un sitio de una página funciona mejor cuando el mensaje está enfocado. Organizamos historia, servicios, evidencia y contacto en un recorrido natural.'),parts:[t('A first impression with purpose','Una primera impresión con propósito'),t('Your offer, explained simply','Tu propuesta, explicada con claridad'),t('A direct path to conversation','Un camino directo a la conversación')],fit:t('For a focused business, a new offer, a campaign or a clear first step online.','Para un negocio enfocado, una nueva oferta, una campaña o un primer paso digital claro.')},
 'business-websites':{eyebrow:t('BUSINESS WEBSITES','SITIOS EMPRESARIALES'),title:t('A stronger presence.<br><span>A bigger possibility.</span>','Una presencia más sólida.<br><span>Más posibilidades.</span>'),copy:t('A professional website that gives your services room to breathe, helps customers find what they need and supports the way your business grows.','Un sitio profesional que presenta tus servicios con claridad, ayuda a tus clientes a encontrar lo que necesitan y acompaña el crecimiento de tu negocio.'),features:[t('Purposeful multi-page structure','Estructura multipágina con propósito'),t('A distinct brand experience','Una experiencia propia de marca'),t('Content, forms and integrations','Contenido, formularios e integraciones')],benefit:t('Built around your business.<br>Ready for its next chapter.','Pensado para tu negocio.<br>Preparado para su siguiente etapa.'),explanation:t('We connect strategy, information architecture, design and development. Every page has a job — and every visitor has a clear way forward.','Conectamos estrategia, arquitectura de información, diseño y desarrollo. Cada página cumple una función y cada visitante encuentra cómo avanzar.'),parts:[t('A structure people understand','Una estructura que se entiende'),t('An identity people recognize','Una identidad que se reconoce'),t('A website your team can grow','Un sitio que tu equipo puede hacer crecer')],fit:t('For growing businesses with multiple services, audiences, locations or content needs.','Para empresas con varios servicios, audiencias, ubicaciones o necesidades de contenido.')},
 'e-commerce':{eyebrow:t('E-COMMERCE DEVELOPMENT','DESARROLLO E-COMMERCE'),title:t('From first look.<br><span>To confident purchase.</span>','De la primera mirada.<br><span>A una compra con confianza.</span>'),copy:t('Online stores that bring your products, brand and operations together — with a considered path from discovery to checkout.','Tiendas online que conectan productos, marca y operaciones, con un recorrido cuidado del descubrimiento a la compra.'),features:[t('Product discovery and navigation','Exploración de productos y navegación'),t('Considered product and checkout flows','Fichas y recorridos de compra claros'),t('Operations and integration planning','Planificación de operaciones e integraciones')],benefit:t('More than a storefront.<br>A connected buying experience.','Más que un escaparate.<br>Una experiencia de compra conectada.'),explanation:t('We define the catalog, customer journey, payment requirements and operational connections together. Platforms and integrations are selected for the project.','Definimos juntos el catálogo, el recorrido del cliente, los requisitos de pago y las conexiones operativas. La plataforma y las integraciones se eligen para cada proyecto.'),parts:[t('Help people find the right product','Ayuda a encontrar el producto adecuado'),t('Give every detail a purpose','Dale un propósito a cada detalle'),t('Connect the purchase to operations','Conecta la compra con la operación')],fit:t('For businesses ready to sell products online or improve an existing store.','Para negocios que quieren vender productos online o mejorar una tienda existente.')}
};
function storeConcept(){return `<div class="store-concept"><div class="browser-top"><i></i><i></i><i></i><span>${t('E-commerce design study','Estudio de diseño e-commerce')}</span></div><div class="store-nav">OBJECTS / 01<span>${t('Collection · Our story','Colección · Nuestra historia')}<b>↗</b></span></div><div class="store-title"><strong>${t('Everyday.<br>Considered.','Cada día.<br>Con intención.')}</strong><span>${t('A visual concept for a connected shopping experience.','Un concepto visual para una experiencia de compra conectada.')}</span></div><div class="store-products"><div><div class="object bottle"><i></i></div><p>${t('Product concept / 01','Concepto de producto / 01')}</p></div><div><div class="object vessel"><i></i></div><p>${t('Product concept / 02','Concepto de producto / 02')}</p></div></div><div class="store-bottom">${t('CONCEPT STUDY — NOT A CLIENT PROJECT','ESTUDIO CONCEPTUAL — NO ES UN PROYECTO DE CLIENTE')} ↗</div></div>`;}
function landing(slug){const d=landingData[slug];return `<section class="landing-hero wrap"><div class="breadcrumb"><a href="${home}">CONNEXION</a><span>/</span><a href="${home}#solutions">${t('SOLUTIONS','SOLUCIONES')}</a><span>/ ${d.eyebrow}</span></div><div class="landing-hero-grid"><div><span class="eyebrow"><i class="status-dot"></i> ${d.eyebrow}</span><h1>${d.title}</h1><p>${d.copy}</p><div class="actions">${btn(t('GET A CUSTOM PROPOSAL','SOLICITA UNA PROPUESTA'),`data-proposal data-interest="${d.eyebrow}"`)}</div><div class="landing-proof">${d.features.map(f=>`<span>↗ ${f}</span>`).join('')}</div></div><figure class="landing-art">${slug==='e-commerce'?storeConcept():miniBrowser(slug==='one-page-websites'?'one-page':'business')}<figcaption>${t('Visual concept for approval. No client or performance claims.','Concepto visual para revisión. No representa un cliente ni resultados.')}</figcaption></figure></div><div class="landing-fit"><span>${t('THE RIGHT FIT','PARA QUIÉN')}</span><p>${d.fit}</p><button data-meeting>${t('Let’s discuss your goals','Conversemos sobre tus objetivos')} ↗</button></div></section><section class="section landing-value"><div class="wrap">${sectionHead('01',t('DESIGNED AROUND YOUR CUSTOMER','DISEÑADO PARA TU CLIENTE'))}<div class="section-heading"><h2>${d.benefit}</h2><p>${d.explanation}</p></div><div class="value-strips">${d.parts.map((f,i)=>`<article><span>0${i+1}</span><h3>${f}</h3><p>${[t('We begin with your audience and a clear direction.','Empezamos por tu audiencia y una dirección clara.'),t('Design and content work together to make the next step easier.','Diseño y contenido trabajan juntos para facilitar el siguiente paso.'),t('Forms, content and selected systems connect the experience to your team.','Formularios, contenido y sistemas seleccionados conectan la experiencia con tu equipo.')][i]}</p></article>`).join('')}</div></div></section><section class="section landing-scope"><div class="wrap scope-grid"><div>${sectionHead('02',t('A CLEAR SCOPE. A SHARED DIRECTION.','ALCANCE CLARO. DIRECCIÓN COMPARTIDA.'))}<h2>${t('Thought through.<br>From the start.','Bien pensado.<br>Desde el comienzo.')}</h2><p>${t('Your proposal defines the deliverables, requirements and milestones. The following is a starting point for the conversation.','La propuesta define entregables, requisitos e hitos. Lo siguiente es un punto de partida para la conversación.')}</p></div><div>${[t('Discovery & content planning','Descubrimiento y planificación de contenido'),t('Information architecture & customer journey','Arquitectura de información y recorrido del cliente'),t('Responsive visual design','Diseño visual responsive'),slug==='e-commerce'?t('Catalog, payments & operational requirements','Catálogo, pagos y requisitos operativos'):t('Website development & content setup','Desarrollo web y preparación de contenido'),t('Forms & selected integrations','Formularios e integraciones seleccionadas'),t('Accessibility, SEO foundations & launch review','Accesibilidad, bases de SEO y revisión de lanzamiento')].map((s,i)=>`<div class="scope-row"><span>0${i+1}</span>${s}<b>↗</b></div>`).join('')}</div></div></section>${processSection()}${slug==='business-websites'?`<section class="section landing-case"><div class="wrap">${sectionHead('03',t('RELEVANT WORK','TRABAJO RELACIONADO'))}<div class="section-heading"><h2>${t('A real business.<br>A clear digital presence.','Un negocio real.<br>Una presencia digital clara.')}</h2><p>MCS Solutions / ${t('Commercial cleaning in Houston. Existing portfolio reference.','Limpieza comercial en Houston. Referencia real del portfolio.')}</p></div><a class="wide-case" href="https://mcssol.net/" target="_blank" rel="noopener"><img src="/assets/work-mcs.webp" alt="MCS Solutions website" loading="lazy"/></a></div></section>`:`<section class="section landing-case"><div class="wrap concept-case-grid"><div>${sectionHead('03',t('DESIGN STUDY','ESTUDIO DE DISEÑO'))}<h2>${t('A considered experience.<br>In every detail.','Una experiencia cuidada.<br>En cada detalle.')}</h2><p>${t('This visual study demonstrates the proposed design language. It is not presented as a completed client project.','Este estudio visual muestra el lenguaje de diseño propuesto. No se presenta como un proyecto de cliente terminado.')}</p></div><div>${slug==='e-commerce'?storeConcept():miniBrowser('one-page')}</div></div></section>`}${faqSection([faq[0],faq[1],faq[5],faq[6],faq[7]])}${finalCTA()}`;}
function systemPage(){return `<section class="section system-page wrap">${sectionHead('PHASE 01',t('DESIGN SYSTEM','SISTEMA DE DISEÑO'))}<h1>${t('The Connection<br><span>System.</span>','El sistema<br><span>Connexion.</span>')}</h1><p class="large-copy">${t('A contrasting light-and-dark identity for human creativity and intelligent technology.','Una identidad de contrastes claros y oscuros para la creatividad humana y la tecnología inteligente.')}</p><div class="swatches">${[['#F7F8F4','WHITE'],['#111A1A','CARBON'],['#B6FF12','CONNEXION GREEN'],['#0E2E1E','DEEP GREEN'],['#4B5856','MEDIUM GRAY'],['#D9DEDC','LIGHT GRAY'],['#E3FF7A','SOFT GREEN']].map(([hex,name])=>`<div><i style="background:${hex}"></i><b>${name}</b><span>${hex}</span></div>`).join('')}</div><div class="system-type"><div><span class="micro">DEJAVU SANS / BOLD 700</span><h2>${t('Human ideas.<br>Intelligent connections.','Ideas humanas.<br>Conexiones inteligentes.')}</h2></div><div><span class="micro">DEJAVU SANS / REGULAR 400</span><p>${t('Technology creates possibilities. Human connection creates value.','La tecnología crea posibilidades. La conexión humana crea valor.')}</p><p>H1 56–72 / H2 48 / H3 26<br>Body 16 / UI 14 / Labels 12<br>Mobile H1 40–44 / H2 32 / H3 22–24</p></div></div><div class="system-controls"><div><span class="micro">${t('ACTIONS','ACCIONES')}</span><div class="actions">${btn(t('Primary action','Acción principal'),'data-proposal')}${btn(t('Secondary action','Acción secundaria'),'data-meeting',true)}</div>${link(t('Editorial link','Enlace editorial'),`${home}#solutions`)}</div><div><span class="micro">${t('GRID & RHYTHM','RETÍCULA Y RITMO')}</span><p>${t('Adaptive grid · 1,320 px content max · 56 px desktop margins · 20–24 px mobile margins.','Retícula adaptable · contenido máximo 1320 px · márgenes desktop 56 px · móvil 20–24 px.')}</p><div class="spacing-samples">${[8,16,24,40,64,96].map(n=>`<span style="width:${n}px">${n}</span>`).join('')}</div></div></div><div class="system-guidelines">${[[t('Surfaces & hierarchy','Superficies y jerarquía'),t('A dark photographic hero leads into white service chapters and charcoal editorial sections. Lime connects the visual system and highlights actions.','El hero fotográfico oscuro abre un recorrido de servicios claros y secciones editoriales negras. El lima conecta el sistema visual y destaca las acciones.')],[t('Motion','Movimiento'),t('Only the hero uses a short scroll sequence. Other interactions explain selection, workflow or process. All essential copy remains readable without animation.','Solo el hero usa una secuencia breve de scroll. Las otras interacciones explican selección, flujo o proceso. El contenido esencial no depende de la animación.')],[t('Responsive behavior','Comportamiento responsive'),t('Mobile moves the connection engine above the message, stacks service stories, makes workflows horizontally explorable and keeps proposal actions within easy reach.','En móvil, el motor de conexiones precede al mensaje, los servicios se apilan, los flujos se exploran en horizontal y las acciones de contacto quedan accesibles.')],[t('Forms & accessibility','Formularios y accesibilidad'),t('Visible labels, clear consent, native fields, keyboard focus and reduced motion. Preview forms demonstrate states without sending or storing personal information.','Etiquetas visibles, consentimiento claro, campos nativos, foco de teclado y movimiento reducido. Los formularios de la vista previa muestran estados sin enviar ni guardar datos personales.')]].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section>`;}
function reviewPage(){return `<section class="section review-page wrap">${sectionHead('PHASE 01',t('COMPLETE DESIGN PROPOSAL','PROPUESTA VISUAL COMPLETA'),t('AWAITING DESIGN APPROVAL','PENDIENTE DE APROBACIÓN VISUAL'))}<h1>${t('First, the design.<br><span>Then, the connection.</span>','Primero, el diseño.<br><span>Después, la conexión.</span>')}</h1><p class="large-copy">${t('Review the dark photographic hero, white service chapters and black editorial sections, the four-scene Connection Engine and the existing interactive pages. This remains a design preview.','Revisa el hero fotográfico oscuro, los servicios claros y las secciones editoriales negras, las cuatro escenas del Connection Engine y las páginas interactivas existentes. Esta versión sigue siendo una vista previa.')}</p><div class="review-links">${[['',t('Complete homepage','Home completa')],['services/one-page-websites',t('One-page websites','Sitios de una página')],['services/business-websites',t('Business websites','Sitios empresariales')],['services/e-commerce',t('E-commerce development','Desarrollo e-commerce')],['storyboard',t('Four-scene hero storyboard','Storyboard de cuatro escenas')],['design-system',t('Design system','Sistema de diseño')],['how-websites-connect',t('The anatomy of a website inquiry','La anatomía de una consulta web')],['how-ai-agents-work',t('AI agent operations','Cómo funciona un agente de IA')]].map(([route,title],i)=>`<a href="/${lang}${route?'/'+route:''}"><span>0${i+1}</span><span class="review-entry-title">${title}</span>${arrow}</a>`).join('')}</div><figure class="revision-comparison"><span class="micro">${t('REVISION 01 → REVISION 02','REVISIÓN 01 → REVISIÓN 02')}</span><h2>${t('The same connection.<br><span>A new atmosphere.</span>','La misma conexión.<br><span>Una nueva atmósfera.</span>')}</h2><p>${t('The previous light proposal and the new light-and-dark direction, at the same initial hero state. The four-scene logo animation is preserved.','La propuesta clara anterior y la nueva dirección de contrastes, con el mismo estado inicial del hero. Se conserva la animación del logo en cuatro escenas.')}</p><img src="/deliverables/comparison-light-dark.png" alt="${t('Previous light homepage hero on the left; revised white and pearl hero on the right.','Hero claro anterior a la izquierda; revisión blanca con efectos perlados a la derecha.')}"/><figcaption>${t('Previous visual proposal / Revised visual proposal — not a comparison of live production websites.','Propuesta visual anterior / Propuesta visual revisada; no es una comparación de webs de producción.')}</figcaption></figure><div class="review-comparison"><div><span class="micro">${t('DARK REFERENCE / SUPPLIED IMAGE','REFERENCIA OSCURA / IMAGEN SUMINISTRADA')}</span><img src="/assets/reference-dark.webp" alt="${t('Supplied dark design reference','Referencia de diseño oscura suministrada')}"/></div><div><h2>${t('A change in hierarchy.<br>Not just background.','Un cambio de jerarquía.<br>No solo de fondo.')}</h2><ul><li>${t('AI, AI agents and web development become the core commercial story.','IA, agentes y desarrollo web pasan al centro de la propuesta comercial.')}</li><li>${t('Charcoal surfaces, luminous connection paths and lime feature panels bring the supplied references into the Connexion identity.','Fondos carbón, conexiones luminosas y paneles lima trasladan las referencias a la identidad de Connexion.')}</li><li>${t('A short connection narrative replaces the prolonged brain transformation.','Una narrativa breve de conexión reemplaza la transformación prolongada del cerebro.')}</li><li>${t('Custom proposals replace public service prices.','Las propuestas a medida sustituyen los precios públicos.')}</li><li>${t('Seven portfolio websites, a clear workflow study and scoped services support the commercial story.','Siete sitios del portafolio, un flujo ilustrativo claro y servicios definidos respaldan la propuesta comercial.')}</li></ul><p class="review-note">${t('The previous application source and full-page captures are no longer present in the project folder. This comparison uses the supplied reference image and the documented previous structure; it is not labeled as a fresh screenshot of a running production site.','El código de la aplicación anterior y sus capturas completas ya no están en la carpeta. Esta comparación utiliza la referencia suministrada y la estructura documentada; no se presenta como una captura reciente de una web de producción activa.')}</p></div></div></section>`;}
function storyboardPage(){const names=[t('The symbol','El símbolo'),t('Activation','Activación'),t('Intelligent connections','Conexiones inteligentes'),t('The reveal','La revelación')];return `<section class="section storyboard-page wrap">${sectionHead('CONNECTION ENGINE',t('HERO STORYBOARD / FOUR SCENES','STORYBOARD DEL HERO / CUATRO ESCENAS'))}<h1>${t('One symbol.<br><span>Infinite possibilities.</span>','Un símbolo.<br><span>Infinitas posibilidades.</span>')}</h1><p class="large-copy">${t('The official symbol activates a connected system of brands, technology and people. A brief scroll sequence, with the commercial message visible from the start.','El símbolo oficial activa un sistema de marcas, tecnología y personas. Una secuencia breve de scroll, con el mensaje comercial visible desde el inicio.')}</p><div class="storyboard-grid">${names.map((name,i)=>`<figure><img src="/deliverables/hero-${i+1}.png" alt="${name}"/><figcaption><span>0${i+1} / ${name}</span><strong>${[t('Great ideas begin with a connection.','Las grandes ideas comienzan con una conexión.'),t('Technology creates possibilities.','La tecnología crea posibilidades.'),t('People make them meaningful.','Las personas les dan sentido.'),t('WE CONNECT BRANDS WITH PEOPLE.','CONECTAMOS MARCAS CON PERSONAS.')][i]}</strong></figcaption></figure>`).join('')}</div>${link(t('Explore the interactive hero','Explora el hero interactivo'),home)}</section>`;}
function inlineContactForm(){return modal().match(/<form id="design-form">[\s\S]*?<\/form>/)[0].replace('id="design-form"','class="inline-design-form"');}
function modal(){return `<dialog id="proposal-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="${t('Close form','Cerrar formulario')}">×</button><span class="eyebrow">${t('THE NEXT CONNECTION','LA PRÓXIMA CONEXIÓN')}</span><h2 id="dialog-title">${t('Tell us what’s next.','Cuéntanos qué sigue.')}</h2><p id="dialog-intro">${t('A few details to start a useful conversation.','Algunos detalles para comenzar una buena conversación.')}</p><form id="design-form"><div class="form-row"><label>${t('Your name','Tu nombre')}<input name="name" autocomplete="name" required placeholder="${t('Full name','Nombre completo')}"></label><label>${t('Work email','Correo de trabajo')}<input name="email" type="email" autocomplete="email" required placeholder="you@company.com"></label></div><div class="form-row"><label>${t('Company','Empresa')}<input name="company" autocomplete="organization" placeholder="${t('Your business','Tu negocio')}"></label><label>${t('What do you need?','¿Qué necesitas?')}<select name="interest"><option value="Website Development">${t('Website Development','Desarrollo web')}</option><option value="AI Solutions">${t('AI Solutions','Soluciones de IA')}</option><option value="AI Agents">${t('AI Agents','Agentes de IA')}</option><option>${t('Branding & marketing','Branding y marketing')}</option><option>${t('Let’s define it together','Definámoslo juntos')}</option></select></label></div><label>${t('What are you working on?','¿En qué estás trabajando?')}<textarea name="message" required placeholder="${t('Your goals, the challenge and what you want to build.','Tus objetivos, el reto y lo que te gustaría construir.')}"></textarea></label><div class="meeting-fields" hidden><div class="form-row"><label>${t('Preferred day','Día de preferencia')}<input type="date" name="day"></label><label>${t('Preferred time & time zone','Hora y zona horaria')}<input name="time" placeholder="${t('e.g. 10:00, Houston','Ej. 10:00, Bogotá')}"></label></div><p>${t('This is a meeting request, not a confirmed booking.','Esta es una solicitud de reunión, no una reserva confirmada.')}</p></div><label class="consent"><input type="checkbox" required><span>${t('I agree to being contacted about this inquiry.','Acepto que me contacten para responder esta consulta.')}</span></label><p class="preview-form-note">${t('Sending opens WhatsApp with your message ready to send.','Al enviar se abre WhatsApp con tu mensaje listo para enviar.')}</p>${btn(t('REQUEST A PROPOSAL','SOLICITA UNA PROPUESTA'),'type="submit"')}<p role="status" class="form-status" hidden></p></form><div class="dialog-alternatives"><button type="button" data-meeting>${t('Prefer a meeting?','¿Prefieres una reunión?')} ↗</button><a href="https://wa.me/13214513964" target="_blank" rel="noopener">WhatsApp ↗</a></div></dialog>`;}
