document.querySelectorAll('[data-proposal]').forEach(b=>b.addEventListener('click',()=>openForm(false,b.dataset.interest)));document.querySelectorAll('[data-meeting]').forEach(b=>b.addEventListener('click',()=>openForm(true)));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});function sendWhatsApp(f,meeting){const v=n=>(f.elements[n]?.value||'').trim();const lines=[meeting?t('Hi Connexion, I would like to request a meeting.','Hola Connexion, quiero solicitar una reunión.'):t('Hi Connexion, I would like a proposal.','Hola Connexion, quiero solicitar una propuesta.'),'',t('Name','Nombre')+': '+v('name'),t('Email','Correo')+': '+v('email')];if(v('company'))lines.push(t('Company','Empresa')+': '+v('company'));if(v('interest'))lines.push(t('Interest','Interés')+': '+v('interest'));if(meeting&&(v('day')||v('time')))lines.push(t('Preferred time','Horario preferido')+': '+[v('day'),v('time')].filter(Boolean).join(' '));lines.push('',v('message'));window.open('https://wa.me/13214513964?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener');const s=f.querySelector('.form-status');s.textContent=t('WhatsApp opened with your message. Press send there to reach us.','Abrimos WhatsApp con tu mensaje. Presiona enviar allí para contactarnos.');s.hidden=false;}
