 const root=document.querySelector('.hero-scroll'),canvas=document.querySelector('#engine');const media=matchMedia('(prefers-reduced-motion: reduce)');const captions=[t('Great ideas begin with a connection.','Las grandes ideas comienzan con una conexión.'),t('Technology creates possibilities.','La tecnología crea posibilidades.'),t('People make them meaningful.','Las personas les dan sentido.'),t('WE CONNECT BRANDS WITH PEOPLE.','CONECTAMOS MARCAS CON PERSONAS.')];let engine,raf=0,last=-1;
 const headerHeight=()=>document.querySelector('.header').getBoundingClientRect().height;
 let heroViewportWidth=innerWidth,heroViewportHeight=innerHeight;
 const layoutHero=()=>{root.style.setProperty('--hero-viewport',`${heroViewportHeight-headerHeight()}px`);root.style.setProperty('--hero-travel',`${Math.round(Math.max(650,heroViewportHeight*1.3))}px`);};layoutHero();
 const referenceHeight=()=>matchMedia('(max-width:800px)').matches?heroViewportHeight:innerHeight;
 const draw=()=>{raf=0;const range=root.offsetHeight-referenceHeight()+headerHeight();const p=Math.max(0,Math.min(1,(headerHeight()-root.getBoundingClientRect().top)/Math.max(1,range)));if(last===p)return;last=p;engine?.render(p);root.style.setProperty('--hero-progress',p);root.style.setProperty('--tag-opacity',Math.max(0,Math.min(1,(p-.4)*4)));const stage=Math.min(3,Math.floor(p*4));root.dataset.stage=String(stage);document.querySelector('#hero-caption').textContent=captions[stage];document.querySelectorAll('.hero-stages button[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.stage)===stage)));};
 const schedule=()=>{if(!raf)raf=requestAnimationFrame(draw);};
 if(media.matches){root.classList.add('reduced');root.dataset.renderer='static';}else{let started=false;const startEngine=()=>{if(started)return;started=true;document.fonts.ready.then(()=>import('/assets/engine.js')).then(m=>m.mountConnectionEngine(canvas)).then(e=>{engine=e;root.dataset.renderer='webgl';last=-1;draw();}).catch(()=>{root.classList.add('reduced');root.dataset.renderer='fallback';});};root.dataset.renderer='poster';addEventListener('scroll',()=>{startEngine();schedule();},{passive:true});root.querySelectorAll('.hero-stages button').forEach(button=>button.addEventListener('click',startEngine,{once:true}));addEventListener('resize',()=>{if(Math.abs(innerWidth-heroViewportWidth)>3||Math.abs(innerHeight-heroViewportHeight)>120){heroViewportWidth=innerWidth;heroViewportHeight=innerHeight;layoutHero();}last=-1;schedule();});}
 document.querySelectorAll('.hero-stages button[data-stage]').forEach(b=>b.addEventListener('click',()=>{const p=Number(b.dataset.stage)===3?1:(Number(b.dataset.stage)+.15)/4;scrollTo({top:scrollY+root.getBoundingClientRect().top-headerHeight()+(root.offsetHeight-referenceHeight()+headerHeight())*p,behavior:'instant'});}));
 window.designHero={setProgress(p){engine?.render(p);root.style.setProperty('--tag-opacity',Math.max(0,Math.min(1,(p-.4)*4)));const s=Math.min(3,Math.floor(p*4));root.dataset.stage=String(s);document.querySelector('#hero-caption').textContent=captions[s];document.querySelectorAll('.hero-stages button[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.stage)===s)));},get ready(){return !!engine;}};
 addEventListener('pagehide',()=>{cancelAnimationFrame(raf);engine?.dispose();},{once:true});
