const visualItems=document.querySelectorAll('.visual-reveal,.core .web-visual,.connection-diagram,.agent-visual');
if(!motionPreference.matches&&'IntersectionObserver' in window){
 const visualObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;visualObserver.unobserve(el);el.dataset.visualState='entered';el.animate([{opacity:.35,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(0.23,1,0.32,1)'});const route=el.querySelector('.signal-path'),signal=el.querySelector('.art-signal');if(route&&signal){const length=route.getTotalLength();const frames=Array.from({length:41},(_,i)=>{const p=route.getPointAtLength(length*i/40);return {transform:`translate(${p.x}px,${p.y}px)`,opacity:i===0||i===40?0:1};});signal.animate(frames,{duration:1600,delay:180,easing:'linear'});}}),{threshold:.18});visualItems.forEach(el=>visualObserver.observe(el));addEventListener('pagehide',()=>visualObserver.disconnect(),{once:true});
}

if(page==='how-websites-connect')import('/assets/anatomy-runtime.js').then(m=>m.mountAnatomy()).catch(()=>{const status=document.querySelector('.machine-readout');if(status)status.textContent=t('Static illustration. Interactive controls are unavailable.','Ilustración estática. Los controles interactivos no están disponibles.');});

if(page==='how-ai-agents-work')import('/assets/ai-operations-runtime.js').then(m=>m.mountAgentEngine()).catch(()=>{const el=document.querySelector('[data-agent-mode]');if(el)el.textContent=t('Static illustration. Interactive controls unavailable.','Ilustración estática. Controles interactivos no disponibles.');});

document.querySelectorAll('.inline-design-form').forEach(inline=>inline.addEventListener('submit',e=>{e.preventDefault();sendWhatsApp(inline,false);}));

document.querySelectorAll('svg[role=img]:not([aria-label]):not([aria-labelledby])').forEach(svg=>svg.setAttribute('aria-label',svg.closest('figure')?.getAttribute('aria-label')||t('Connected business systems','Sistemas de negocio conectados')));

import('/premium.js').catch(()=>{});
